from itertools import permutations
import math

def max_empty_square(perm, n):
    rooks = [(i, perm[i]) for i in range(n)]
    best = 0
    for k in range(1, n+1):
        found = False
        for r in range(n - k + 1):
            for c in range(n - k + 1):
                empty = True
                for i in range(r, r + k):
                    if c <= perm[i] < c + k:
                        empty = False
                        break
                if empty:
                    found = True
                    break
            if found:
                break
        if found:
            best = k
    return best

# For larger n, we can't enumerate all permutations, but let's try to check
# if the identity permutation gives floor(sqrt(n-1)) and if we can construct
# a permutation that achieves this bound.

# First, let's verify the pattern for small n
for n in range(2, 10):
    worst = n
    worst_perm = None
    for perm in permutations(range(n)):
        k = max_empty_square(perm, n)
        if k < worst:
            worst = k
            worst_perm = perm
    predicted = int(math.isqrt(n - 1))
    print(f"n={n}: k={worst}, predicted floor(sqrt(n-1))={predicted}, match={worst==predicted}")
